parameters.jsCode:
const output = [];

for (const item of items) {
  const term = item.json.term;
  const searchResults = item.json.query?.search || [];

  for (const result of searchResults) {
    output.push({
      json: {
        term,
        wiki_title: result.title,
        wiki_pageid: result.pageid,
        wiki_url: `https://en.wikipedia.org/wiki/${result.title.replace(/ /g, "_")}`,
        wiki_snippet: result.snippet
      }
    });
  }
}

return output;

